syntax:
void constructor(struct MyStruct *obj) {
    obj->member1 = initial_value1;
    obj->member2 = initial_value2;
    // initialize all members explicitly
}

code_example:
struct Data {
    int a;
    double b;
    char c;
};

void initData(struct Data *d) {
    d->a = 0;             // Explicitly initialize integer member
    d->b = 0.0;           // Explicitly initialize double member
    d->c = '\0';        // Explicitly initialize char member
}

int main() {
    struct Data myData;
    initData(&myData);    // Constructor explicitly initializes all members
    // Now myData is in a well-defined state
    return 0;
}
